const DEDUCTIBLE = 100;
const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
};
const CAP_FACTOR = 2;

const payoutOfDamage = (damage: Damage): number => damage.amount - DEDUCTIBLE;

const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

const claim = (step: ClaimStep, policyItems: Item[]): ClaimResult => {
  const payout = payoutOfDamage(step.incident.damages[0]);
  return {
    payout,
    remainingCap: CAP_FACTOR * insuranceSum(policyItems) - payout,
  };
};

const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";

const quoteSteps = (steps: Step[]): QuoteStep[] => steps.filter(isQuoteStep);

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step, previousQuoteCount) =>
    isQuoteStep(step)
      ? quote(step.items, scenario.customer, previousQuoteCount)
      : claim(step, quoteSteps(scenario.steps)[step.policy].items),
  ),
});
